export const fontFamily = 'Inter, system-ui, sans-serif'
export const lineHeight = 1.25
/** Where the first baseline sits below the top of a line box, in ems. */
export const baseline = 0.98

/** Shortens text to at most this many UTF-8 bytes, as the server counts them. */
export function clip(text: string, bytes: number): string {
  const encoder = new TextEncoder()
  while (encoder.encode(text).length > bytes) text = text.slice(0, -1)
  return text
}

let context: CanvasRenderingContext2D | null = null

/** The box a text shape needs. Stored on the shape so every peer selects the same area. */
export function measureText(text: string, fontSize: number): { w: number; h: number } {
  // Outside a browser, such as in unit tests, widths are estimated.
  context ??= typeof document === 'undefined' ? null : document.createElement('canvas').getContext('2d')
  const lines = text.split('\n')
  let width = 0
  if (context) {
    context.font = `${fontSize}px ${fontFamily}`
    for (const line of lines) width = Math.max(width, context.measureText(line).width)
  } else {
    width = Math.max(...lines.map((line) => line.length)) * fontSize * 0.6
  }
  return { w: Math.ceil(width), h: Math.ceil(lines.length * fontSize * lineHeight) }
}
